<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $m=current_medico(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf(); if(isset($_FILES['arquivo'])&&$_FILES['arquivo']['error']===UPLOAD_ERR_OK){$fh=fopen($_FILES['arquivo']['tmp_name'],'r');$n=0;while(($row=fgetcsv($fh,0,';'))!==false){$code=trim($row[0]??'');$desc=trim($row[1]??'');if($code===''||$desc==='')continue;$s=db()->prepare('INSERT INTO cids(codigo,descricao,fonte,versao) VALUES(?,?,?,?) ON CONFLICT(codigo) DO UPDATE SET descricao=excluded.descricao,fonte=excluded.fonte,versao=excluded.versao');$s->execute([$code,$desc,'importacao','CID-10']);$n++;}fclose($fh);$msg=$n.' registros processados.';}else{$msg='Selecione um CSV válido.';}} render_header('Importar CID-10');?><h1>Importar base CID-10</h1><div class="card"><p>CSV esperado: <b>codigo;descricao</b>. O conteúdo é gravado no SQLite separado do sistema principal.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="file" name="arquivo" accept=".csv,text/csv" required><br><br><button class="btn ok">Importar</button></form><?php if($msg):?><p class="success"><?=e($msg)?></p><?php endif;?></div><?php render_footer(); ?>